const fs=require('node:fs'),assert=require('node:assert/strict');
const {H,L,E,seed,next,step,finishRound,canonical,OUT,sha}=require('./simulate-walkthrough-p2-20261101.cjs');
const s=seed();assert(L.normalize(s));const started=performance.now(),start=s.time;let remaining=86400,elapsed=0,compensation=0,steps=0,reportAt=performance.now();
while(remaining>1e-7){const dt=Math.min(remaining,next(s));step(s,dt);const y=dt-compensation,total=elapsed+y;compensation=(total-elapsed)-y;elapsed=total;remaining=Math.max(0,86400-elapsed);steps++;if(performance.now()-reportAt>15000){console.log(JSON.stringify({simulation:'P2 native 1 day compensated clock',elapsed:86400-remaining,round:s.legacy.round,wallSeconds:(performance.now()-started)/1000,steps}));reportAt=performance.now();}}
const raw=H.exportStr(s);fs.writeFileSync(OUT+'/checkpoint-1day-native-compensated.ht5',raw);const restored=H.importStr(raw);assert.equal(restored.legacy.round,s.legacy.round);const result={label:'1day',seconds:86400,native:true,wallSeconds:(performance.now()-started)/1000,steps,round:s.legacy.round,points:s.legacy.points,era:s.era,axiom:s.legacy.axiom,currentRoundSeconds:s.time-s.legacy.roundStart,canonicalHash:sha(canonical(s)),sha256:sha(raw),file:'checkpoint-1day-native-compensated.ht5',stateTime:s.time,clockError:s.time-start-86400};fs.writeFileSync(OUT+'/native-1day-compensated.json',JSON.stringify(result,null,2));console.log(JSON.stringify(result,null,2));
